-- Apply only AFTER the wallet-aware relay is deployed. Missing keys keep models hidden.
-- Public usage rankings, not a claim of verified purchase counts. No balances are credited.
do $$
declare current_config jsonb; extra_models jsonb; extra_providers jsonb;
begin
 select config into current_config from public.tagflow_config where id=1 for update;
 if current_config is null then return; end if;
 select coalesce(jsonb_agg(item),'[]'::jsonb) into extra_models from jsonb_array_elements($catalogue$[{"id":"paid-deepseek-flash","name":"DeepSeek V4.1 Flash 1017 (Direct)","provider":"custom-deepseek","upstreamModel":"deepseek-flash","inputPrice":0.3,"outputPrice":1.2,"cacheInputPrice":0.006,"billing":"wallet","enabled":true,"contextWindow":1000000,"maxOutput":8192,"pricingSchedule":"deepseek"},{"id":"paid-gpt6-luna","name":"GPT-6 Luna · OpenAI (Direct)","provider":"openai","upstreamModel":"gpt-6-luna","inputPrice":0.1,"outputPrice":0.5,"cacheInputPrice":0.01,"billing":"wallet","enabled":true,"contextWindow":1000000,"maxOutput":8192},{"id":"paid-glm53-flash","name":"GLM 5.3 Flash · Z.ai (Direct)","provider":"custom-zai","upstreamModel":"glm-5.3-flash","inputPrice":0.15,"outputPrice":0.5,"cacheInputPrice":0.03,"billing":"wallet","enabled":true,"contextWindow":1000000,"maxOutput":8192},{"id":"paid-minimax-m31-flash","name":"MiniMax M3.1 Flash (Direct)","provider":"custom-minimax","upstreamModel":"MiniMax-M3.1-Flash","inputPrice":0.15,"outputPrice":0.6,"cacheInputPrice":0.015,"billing":"wallet","enabled":true,"contextWindow":1000000,"maxOutput":8192},{"id":"paid-mimo26-flash","name":"MiMo V2.6 Flash · Xiaomi (Direct)","provider":"custom-xiaomi","upstreamModel":"mimo-v2.6-flash","inputPrice":0.14,"outputPrice":0.28,"cacheInputPrice":0.0028,"billing":"wallet","enabled":true,"contextWindow":1000000,"maxOutput":8192},{"id":"paid-claude-opus55","name":"Claude Opus 5.5 · Anthropic (Direct)","provider":"custom-anthropic","upstreamModel":"claude-opus-5-5","inputPrice":4,"outputPrice":20,"cacheInputPrice":4,"billing":"wallet","enabled":true,"contextWindow":1000000,"maxOutput":8192},{"id":"paid-claude-sonnet55","name":"Claude Sonnet 5.5 · Anthropic (Direct)","provider":"custom-anthropic","upstreamModel":"claude-sonnet-5-5","inputPrice":2,"outputPrice":10,"cacheInputPrice":2,"billing":"wallet","enabled":true,"contextWindow":1000000,"maxOutput":8192},{"id":"paid-glm53","name":"GLM 5.3 · Z.ai (Direct)","provider":"custom-zai","upstreamModel":"glm-5.3","inputPrice":1.4,"outputPrice":4.4,"cacheInputPrice":0.26,"billing":"wallet","enabled":true,"contextWindow":1000000,"maxOutput":8192},{"id":"paid-or-deepseek-deepseek-v4-1-flash-1017","name":"DeepSeek · DeepSeek V4.1 Flash 1017 (OpenRouter)","provider":"openrouter","upstreamModel":"deepseek/deepseek-v4.1-flash-1017","billing":"wallet","enabled":true,"contextWindow":1000000,"maxOutput":8192,"inputPrice":0.3,"outputPrice":1.2,"cacheInputPrice":0.006},{"id":"paid-or-deepseek-deepseek-v4-1-flash","name":"DeepSeek · DeepSeek V4.1 Flash (OpenRouter)","provider":"openrouter","upstreamModel":"deepseek/deepseek-v4.1-flash","billing":"wallet","enabled":true,"contextWindow":1000000,"maxOutput":8192,"inputPrice":0.045,"outputPrice":0.5,"cacheInputPrice":0.006},{"id":"paid-or-z-ai-glm-5-3-flash","name":"Z.ai · GLM 5.3 Flash (OpenRouter)","provider":"openrouter","upstreamModel":"z-ai/glm-5.3-flash","billing":"wallet","enabled":true,"contextWindow":1000000,"maxOutput":8192,"inputPrice":0.15,"outputPrice":0.5,"cacheInputPrice":0.03},{"id":"paid-or-openai-gpt-6-luna","name":"OpenAI · GPT-6 Luna (OpenRouter)","provider":"openrouter","upstreamModel":"openai/gpt-6-luna","billing":"wallet","enabled":true,"contextWindow":1000000,"maxOutput":8192,"inputPrice":0.09999999999999999,"outputPrice":0.5,"cacheInputPrice":0.01},{"id":"paid-or-tencent-hy4-preview","name":"Tencent · Hy4 preview (OpenRouter)","provider":"openrouter","upstreamModel":"tencent/hy4-preview","billing":"wallet","enabled":true,"contextWindow":1000000,"maxOutput":8192,"inputPrice":0.834,"outputPrice":2.501,"cacheInputPrice":0.041999999999999996},{"id":"paid-or-anthropic-claude-opus-5-5","name":"Anthropic · Claude Opus 5.5 (OpenRouter)","provider":"openrouter","upstreamModel":"anthropic/claude-opus-5.5","billing":"wallet","enabled":true,"contextWindow":1000000,"maxOutput":8192,"inputPrice":4,"outputPrice":20,"cacheInputPrice":0.19999999999999998},{"id":"paid-or-stepfun-step-5-preview","name":"StepFun · Step 5 Preview (OpenRouter)","provider":"openrouter","upstreamModel":"stepfun/step-5-preview","billing":"wallet","enabled":true,"contextWindow":1000000,"maxOutput":8192,"inputPrice":1,"outputPrice":2.7,"cacheInputPrice":0.09999999999999999},{"id":"paid-or-z-ai-glm-5-3","name":"Z.ai · GLM 5.3 (OpenRouter)","provider":"openrouter","upstreamModel":"z-ai/glm-5.3","billing":"wallet","enabled":true,"contextWindow":1000000,"maxOutput":8192,"inputPrice":0.0699,"outputPrice":1.4,"cacheInputPrice":0.0689},{"id":"paid-or-xiaomi-mimo-v2-6-flash","name":"Xiaomi · MiMo-V2.6-Flash (OpenRouter)","provider":"openrouter","upstreamModel":"xiaomi/mimo-v2.6-flash","billing":"wallet","enabled":true,"contextWindow":1000000,"maxOutput":8192,"inputPrice":0.14,"outputPrice":0.28,"cacheInputPrice":0.0028},{"id":"paid-or-minimax-minimax-m3-1-flash","name":"MiniMax · MiniMax M3.1 Flash (OpenRouter)","provider":"openrouter","upstreamModel":"minimax/minimax-m3.1-flash","billing":"wallet","enabled":true,"contextWindow":1000000,"maxOutput":8192,"inputPrice":0.15,"outputPrice":0.6,"cacheInputPrice":0.015},{"id":"paid-or-qwen-qwen3-8-flash","name":"Qwen · Qwen3.8 Flash (OpenRouter)","provider":"openrouter","upstreamModel":"qwen/qwen3.8-flash","billing":"wallet","enabled":true,"contextWindow":1000000,"maxOutput":8192,"inputPrice":0.15,"outputPrice":0.47,"cacheInputPrice":0.016},{"id":"paid-or-anthropic-claude-sonnet-5-5","name":"Anthropic · Claude Sonnet 5.5 (OpenRouter)","provider":"openrouter","upstreamModel":"anthropic/claude-sonnet-5.5","billing":"wallet","enabled":true,"contextWindow":1000000,"maxOutput":8192,"inputPrice":2,"outputPrice":10,"cacheInputPrice":0.09999999999999999},{"id":"paid-or-moonshotai-kimi-k3-1-pro","name":"MoonshotAI · Kimi K3.1 Pro (OpenRouter)","provider":"openrouter","upstreamModel":"moonshotai/kimi-k3.1-pro","billing":"wallet","enabled":true,"contextWindow":1000000,"maxOutput":8192,"inputPrice":2,"outputPrice":10,"cacheInputPrice":0.19999999999999998}]$catalogue$::jsonb) item
 where not exists(select 1 from jsonb_array_elements(coalesce(current_config->'models','[]'::jsonb)) old where old->>'id'=item->>'id');
 select coalesce(jsonb_agg(item),'[]'::jsonb) into extra_providers from jsonb_array_elements($catalogue$[{"id":"custom-deepseek","name":"DeepSeek","baseUrl":"https://api.deepseek.com"},{"id":"custom-anthropic","name":"Anthropic","baseUrl":"https://api.anthropic.com/v1"},{"id":"custom-zai","name":"Z.ai","baseUrl":"https://api.z.ai/api/paas/v4"},{"id":"custom-minimax","name":"MiniMax","baseUrl":"https://api.minimax.io/v1"},{"id":"custom-xiaomi","name":"Xiaomi MiMo","baseUrl":"https://api.xiaomimimo.com/v1"}]$catalogue$::jsonb) item
 where not exists(select 1 from jsonb_array_elements(coalesce(current_config->'providers','[]'::jsonb)) old where old->>'id'=item->>'id');
 if jsonb_array_length(coalesce(current_config->'models','[]'::jsonb))+jsonb_array_length(extra_models)>50 then raise exception 'Too many model rows; review the curated catalogue before publishing'; end if;
 update public.tagflow_config set config=jsonb_set(jsonb_set(current_config,'{models}',coalesce(current_config->'models','[]'::jsonb)||extra_models),'{providers}',coalesce(current_config->'providers','[]'::jsonb)||extra_providers),updated_at=floor(extract(epoch from now())*1000)::bigint,updated_by='owner-approved-paid-model-launch' where id=1;
 insert into public.audit_log(admin_uid,action,subject_uid,at) values('owner-approved-paid-model-launch','add-popular-paid-models-35-percent','*',floor(extract(epoch from now())*1000)::bigint);
end $$;
